//! 🧪️ The original factory command keeps its exact string allocations through one-fuel source admission.
use super::*;
fn observe<T>(f:impl FnOnce()->T)->(T,usize,usize){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(v,h.requested_bytes,h.released_bytes)}
fn strings(command:&FlowCommand)->[Option<&str>;6]{match command{FlowCommand::FlowEvalResolve(p)=>[Some(&p.window_id),None,None,None,None,None],FlowCommand::AddWidget(p)=>[Some(&p.kind),p.neuron_kind.as_deref(),p.label.as_deref(),p.action.as_deref(),p.format.as_deref(),None],FlowCommand::NodeGraphEdit(p)=>match p.operations.as_slice(){[super::super::super::node_graph_edit::FlowNodeGraphEditOp::InsertPort{node_id,side,..}]=>[Some(node_id),Some(side),None,None,None,None],_=>[None;6]},FlowCommand::RemoveWidget(p)=>[Some(&p.widget_id),None,None,None,None,None],FlowCommand::Disconnect(p)=>[Some(&p.synapse_id),None,None,None,None,None],FlowCommand::FlowEvalTick(p)=>[Some(&p.window_id),Some(&p.window_kind_id),None,None,None,None],FlowCommand::ConnectMediaPorts(p)=>[Some(&p.source_node_id),Some(&p.source_port_id),Some(&p.target_node_id),Some(&p.target_port_id),None,None],_=>[None;6]}}
fn operation_roster(command:&FlowCommand)->Option<(usize,usize,usize)>{match command{FlowCommand::NodeGraphEdit(p)=>Some((p.operations.as_ptr()as usize,p.operations.len(),p.operations.capacity())),_=>None}}
fn native_roster(command:&FlowCommand)->Option<(usize,usize,usize)>{match command{FlowCommand::FlowEvalResolve(p)=>match p.output.as_ref(){Some(semio_framework_value::DslValue::Object(rows))=>Some((rows.as_ptr()as usize,rows.len(),rows.capacity())),_=>None},_=>None}}
fn scalars(command:&FlowCommand)->(Option<u64>,Option<u64>,Option<u32>){match command{FlowCommand::FlowEvalResolve(p)=>(Some(p.node_hash),None,None),FlowCommand::AddWidget(p)=>(p.x.map(f64::to_bits),p.y.map(f64::to_bits),None),FlowCommand::NodeGraphEdit(p)=>match p.operations.as_slice(){[super::super::super::node_graph_edit::FlowNodeGraphEditOp::InsertPort{index,..}]=>(None,None,Some(*index)),_=>(None,None,None)},_=>(None,None,None)}}

#[test]
fn original_flow_factory_donation_retains_actual_command_fields_under_one_fuel_and_cancel_close(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️donation.json")).unwrap();
  for row in fixture["cases"].as_array().unwrap(){for stop in [None,Some(0),Some(1),Some(2),Some(3)]{
  let((mut command,mut intake),born,free)=observe(||{let fields=row["fields"].as_array().unwrap();let text=|i:usize|fields[i].as_str().unwrap().to_owned();let(tool,command)=match row["tool"].as_str().unwrap(){"flowEvalResolve"=>("flowEvalResolve",FlowCommand::FlowEvalResolve(super::super::super::flow_eval_resolve::FlowEvalResolve{window_id:text(0),node_hash:23,output:row.get("output").filter(|value|!value.is_null()).map(|value|semio_framework_pack_json::from_json_str(&serde_json::to_string(value).unwrap(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap())})),"evaluate"=>("evaluate",FlowCommand::Evaluate(super::super::super::evaluate::Evaluate{})),"flowEvalTick"=>("flowEvalTick",FlowCommand::FlowEvalTick(super::super::super::flow_eval_tick::FlowEvalTick{window_id:text(0),window_kind_id:text(1)})),"connectMediaPorts"=>("connectMediaPorts",FlowCommand::ConnectMediaPorts(super::super::super::connect_media_ports::ConnectMediaPorts{source_node_id:text(0),source_port_id:text(1),target_node_id:text(2),target_port_id:text(3)})),"addWidget"=>("addWidget",FlowCommand::AddWidget(super::super::super::add_widget::AddWidget{kind:text(0),neuron_kind:None,x:Some(-1.5),y:Some(2.25),label:Some(text(1)),action:None,format:None})),"nodeGraphEdit"=>("nodeGraphEdit",FlowCommand::NodeGraphEdit(super::super::super::node_graph_edit::NodeGraphEdit{operations:vec![super::super::super::node_graph_edit::FlowNodeGraphEditOp::InsertPort{node_id:text(0),side:text(1),index:1}]})),"removeWidget"=>("removeWidget",FlowCommand::RemoveWidget(super::super::super::remove_widget::RemoveWidget{widget_id:text(0)})),"disconnect"=>("disconnect",FlowCommand::Disconnect(super::super::super::disconnect::Disconnect{synapse_id:text(0)})),"reorganize"=>("reorganize",FlowCommand::Reorganize(super::super::super::reorganize::Reorganize{})),_=>unreachable!()};(command,FlowOriginalIntake::new(tool))});let original=born-free;let roster=operation_roster(&command);let native=native_roster(&command);let values=scalars(&command);let pointers=strings(&command).map(|s|s.map(str::as_ptr));let bytes=strings(&command).iter().flatten().map(|s|s.len()).sum::<usize>();assert_eq!(bytes,row["bytes"].as_u64().unwrap()as usize);
  let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};let mut caller=semio_framework_job::OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(97146),semio_framework_job::Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);let mut ready=false;
  for turn in 0..200{if stop==Some(turn){break}let(_,born,free)=observe(||caller.turn(RetainedCloneGrant{maximum_items:0,..stock},|cx|cx.with_original_work_loan(1,1500,|cx|{assert!(!intake.receive_command(&mut command,cx)?);Ok(())})).unwrap());assert_eq!((born,free),(0,0));
   let(_,born,free)=observe(||caller.turn(stock,|cx|cx.with_original_work_loan(1,1500,|cx|{ready=intake.receive_command(&mut command,cx)?;Ok(())})).unwrap());let receipt=caller.receipt();assert_eq!((born,free),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=born;releases+=free;if ready{break}
  }
  if stop.is_none(){assert!(ready);let original_command=intake.fields.as_ref().unwrap().command.as_ref().unwrap().try_borrow().unwrap();assert_eq!(original_command.get().command_id(),row["tool"].as_str().unwrap());assert_eq!(scalars(original_command.get()),values);assert_eq!(operation_roster(original_command.get()),roster);assert_eq!(native_roster(original_command.get()),native);if roster.is_some(){assert_eq!(operation_roster(&command).map(|(_,len,capacity)|(len,capacity)),Some((0,0)));}assert_eq!(strings(original_command.get()).map(|s|s.map(str::as_ptr)),pointers);assert_eq!(strings(&command).iter().flatten().map(|s|s.len()).sum::<usize>(),0);}
  if stop.is_some(){caller.cancel().cancel_now();let(_,born,free)=observe(||caller.turn(stock,|cx|cx.with_original_work_loan(1,1500,|cx|{assert!(!intake.receive_command(&mut command,cx)?);Ok(())})).unwrap());assert_eq!((born,free),(0,0));assert_eq!(caller.receipt(),Default::default());}
  intake.begin_close();for _ in 0..100000{if intake.terminal_is_empty(){break}let d=intake.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|intake.close_step(g))?;Ok(())}))).unwrap());let receipt=caller.receipt();assert_eq!((born,free),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=born;releases+=free;}
  assert!(intake.terminal_is_empty());let mut command=semio_framework_value::retirement::controlled::ControlledRetirement::new(command).unwrap_or_else(|_|unreachable!());for _ in 0..100000{if command.terminal_is_empty(){break}let d=command.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|{let result=command.step(g);RetainedWorkOutcome{result,work:command.last_turn_work()}})?;Ok(())}))).unwrap());let receipt=caller.receipt();assert_eq!((born,free),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=born;releases+=free;}assert!(command.terminal_is_empty());assert_eq!(original+births,releases);caller.retire(stock);
 }}
}
